changeSet.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM buchung_mietbereich
        WHERE vereinbarter_preis IS NULL
           OR berechnungsart IS NULL
    ) THEN
        RAISE EXCEPTION
            'Preissnapshot-Migration abgebrochen: Für mindestens eine Buchungsposition fehlt Preis oder Berechnungsart. Bitte fehlende Mietpreise prüfen.';
    END IF;
END;
$$;
